### Program.cs — stdio transport with DI

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: log to stderr only — stdout is the JSON-RPC protocol channel
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient();  // registers IHttpClientFactory + HttpClient

builder.Services.AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

### ApiTools.cs — tool class wrapping a REST API

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch a user by their ID from the REST API.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var json = await httpClient.GetStringAsync(
            $"https://jsonplaceholder.typicode.com/users/{userId}",
            cancellationToken);
        return json;
    }

    [McpServerTool, Description("List all posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Optional user ID to filter posts")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var url = "https://jsonplaceholder.typicode.com/posts";
        if (userId.HasValue)
            url += $"?userId={userId.Value}";

        var json = await httpClient.GetStringAsync(url, cancellationToken);
        return json;
    }

    [McpServerTool(ReadOnly = false, Destructive = false),
     Description("Create a new post via the REST API.")]
    public async Task<string> CreatePost(
        [Description("Title of the post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author's user ID")] int authorId,
        CancellationToken cancellationToken = default)
    {
        var payload = JsonSerializer.Serialize(new { title, body, userId = authorId });
        var content = new StringContent(payload, System.Text.Encoding.UTF8, "application/json");

        var response = await httpClient.PostAsync(
            "https://jsonplaceholder.typicode.com/posts", content, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

